mapper.select:
select r.id AS id, u.nickname AS nickname, u.avatar AS avatar, r.rating AS rating, r.content AS content,
       r.images AS images, r.created_at AS createdAt
from product_review r left join user u on r.user_id = u.id


        AND r.spu_id = #{spuId}


        AND r.rating = #{req.rating}


ORDER BY r.created_at DESC
